function CatHouseExplore:RefreshScrollView(pData)
    local dataList = pData or CatHouseExploreMgr.listTaskData
    if self.List.IsListViewInit then
        GameUtils.ReloadData(self.List, table.count(dataList))
    else
        self.List:InitGridView(table.count(dataList), Bind(self, self.OnGetItemByIndex))
    end
end

function CatHouseExplore:OnGetItemByIndex(gridView, index, row, column)
    if index < 0 then return end
    local indexInTaskData = index + 1
    local indexData = CatHouseExploreMgr.listTaskData[indexInTaskData]
    local prefabPath = PREFAB_TASK_CELL
    local cell = gridView:NewListViewItem(prefabPath)
    if not IsNull(cell) then
        KTool.SetActive(cell.gameObject, true)
        local cellLB = GetLuaBehaviour(cell.gameObject, PATH_LUA_CELL)
        if cellLB then
            if isNull(cellLB.Env) then cellLB:Init() end
            local cellLT = cellLB.Env
            cellLT:FreshUI(indexData)
            if not cell.IsInitHandlerCalled then
                cell.IsInitHandlerCalled = true
                table.insert(self.listTaskCell, cellLT)
                cellLT:SetAnimatorEnabled(true)
            end
        end
    end
    return cell
end

function CatHouseExplore:RefreshRootStarsReward()
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
    ---@type CatHouseHomeDojo
    local catHouseHomeDojo = component:GetCatHouseHomeDojo()
    local exploreBoxId = checkNumber(catHouseHomeDojo.exploreBoxId)
    local exploreBoxProgress = checkNumber(catHouseHomeDojo.exploreBoxProgress)
    local exploreBoxData = CatHouseExploreMgr:GetCatHouseTaskBoxData(exploreBoxId)
    local taskStar = exploreBoxData.star
    self.TextRewardNum.text = string.format("%d/%d", exploreBoxProgress, taskStar)
    local processValue = exploreBoxProgress / taskStar
    self.FilledRewardProcess.fillAmount = processValue > 1 and 1 or processValue
    KTool.SetActive(self.UIFX_CatHouseExploreDialogBox.gameObject, processValue >= 1)
    SetButtonAction(self.BtnReward.gameObject, function()
        if checkNumber(exploreBoxProgress / taskStar) >= 1 then
            CatHouseExploreMgr:CatHouseDrawExploreBox(function()
                self:RefreshRootStarsReward()
            end)
        else
            UIModule.OpenDialog({ id = Constants.UITypeIds.CatHouseExploreRewardPopup, parameters = { boxData = exploreBoxData } })
        end
    end)
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(checkNumber(exploreBoxData.boxId))
    self.ImgReward:LoadSprite(checkString(goodsVo.photoPath))
    GameUtils.UpdateServerRedPointData({catHouseExploreBox = checkNumber(exploreBoxProgress / taskStar) >= 1 and 0 or -1})
end

function CatHouseExplore:UpdateRedPoint()
    CatHouseExploreMgr:GetExploreCellStatus()
    local redPPointStatus = CatHouseExploreMgr:GetExploreCellStatus() and 0 or -1
    if redPPointStatus ~= 0 then
        local redPTime = CatHouseExploreMgr:GetRedPointLeftTime()
        if redPTime > 0 then
            redPPointStatus = redPTime
        end
    end
    GameUtils.UpdateServerRedPointData({catHouseExploreTask = redPPointStatus})
    print("->CatHouseExplore:UpdateRedPoint:", redPPointStatus)
end

function CatHouseExplore:ResetRootExploreRefresh()
    if not isNull(self.RefreshTimesRenind) then
        local rootLuaEnv = self.RefreshTimesRenind.Env
        if isNull(rootLuaEnv) then
            self.RefreshTimesRenind:Init()
            rootLuaEnv = self.RefreshTimesRenind.Env
        end
        rootLuaEnv:ResetInfo()
    end
end

return CatHouseExplore